INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('3e1c29c1-6e00-4632-80b8-86959c38e3f5', '2c5b63b6-4a20-4ce4-be2f-2564f7d347be', 'items', 1, NULL, NULL, NULL, NULL, '{"items":[{"answer":"Investors, business owners, SMEs, government officials, development partners and the general public.","question":"Who can attend MIICCOF?"},{"answer":"Use the Register page to create an account as a delegate, sponsor or exhibitor. You will receive a verification email to activate your account.","question":"How do I register?"},{"answer":"Register as an exhibitor. Booth allocation is managed by the secretariat through the exhibitor portal.","question":"How do I book an exhibition booth?"},{"answer":"Register as a sponsor and the partnerships team will contact you with package details.","question":"How can my organisation sponsor the event?"}]}', '2026-08-13T09:46:07.450Z', '2026-08-13T09:46:07.450Z');
