INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('1a7eb803-7cb7-4c3e-8744-e8b050a927fe', '3495b681-6e19-4615-a8f1-f79f73e92515', 'committee', 4, 'Organising Committee', 'Key representatives driving MIICCOF', NULL, NULL, '{"cards":[{"description":"Representing Meru University of Science and Technology (MUST) as Chairperson of the Organising Committee.","image":"/images/committee/julius-ithae.jpg","role":"Chairperson","title":"Dr. Julius Ithae"},{"description":"Representing the County Government of Meru (MCG) as Vice Chairperson, overseeing trade facilitation.","image":"/images/committee/jacline-kanana.png","role":"Vice Chairperson","title":"Jackline Kanana","zoom":"h-[140%] w-[140%] object-cover object-[center_10%]"},{"description":"Representing KNCCI Meru Chapter as Secretary, coordinating chamber activities and member engagement.","image":"/images/committee/martin-mbui.jpeg","role":"Secretary","title":"Martin Kiogora Mbui"},{"description":"Representing the Meru County Government in logistics, policy coordination and public sector alignment.","image":"/images/committee/kithinji-ruri.jpg","role":"Meru County Government","title":"Kithinji Ruri"},{"description":"Representing Meru University of Science and Technology in academic partnerships and research coordination.","image":"/images/committee/patrick-kubai.jpg","role":"MUST Representative","title":"Dr. Patrick Kinyua Kubai"}],"variant":"committee"}', '2026-08-13T09:46:05.922Z', '2026-09-14T05:32:29.337Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('362e4ff3-5f88-4b8f-9975-ba449e6a74e7', '3495b681-6e19-4615-a8f1-f79f73e92515', 'hero', 0, 'Meru International Investment Conference and Consumer Fair', 'Unlocking investment and trade opportunities in Meru', 'MIICCOF brings together investors, government, business leaders and innovators to showcase opportunities, forge partnerships and drive inclusive growth.', '/images/hero/tea-harvesting.jpeg', '{"badge":"December 3rd, 4th, & 5th 2026","cta":[{"href":"/about","label":"Discover More"},{"href":"/register","label":"Register to Attend"}]}', '2026-08-13T09:46:05.922Z', '2026-09-14T05:15:31.443Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('9272193a-14ce-47b7-af3c-ac00d266a706', '3495b681-6e19-4615-a8f1-f79f73e92515', 'events-preview', 6, 'Scheduled Events', 'Key sessions and activities', NULL, NULL, '{"cta":{"href":"/conference-programme","label":"Full Programme"},"events":[{"description":"Official opening and keynote addresses.","image":"/images/events/opening-ceremony.jpg","time":"Day 1 ┬╖ Morning","title":"Opening Ceremony"},{"description":"Sector panels with investors and government.","image":"/images/events/panel-discussion.jpg","time":"Day 1 ┬╖ Afternoon","title":"Investor Panel Discussions"},{"description":"Exhibition booths and B2B networking.","image":"/images/events/Trade Fair-exhibitions.jpg","time":"All Days","title":"Consumer Fair & Exhibitions"}]}', '2026-08-13T09:46:05.922Z', '2026-09-14T05:15:40.744Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('c5c7d9f4-bef2-4c6f-bead-b76f392267f8', '3495b681-6e19-4615-a8f1-f79f73e92515', 'sponsorship-teaser', 5, 'Sponsorship Packages', 'Partner with us and put your brand at the centre', NULL, NULL, '{"brands":[{"href":"https://meruchamber.co.ke/","image":"/images/brands/kncci-logo.png","name":"KNCCI ??? Meru Chapter"},{"href":"https://www.must.ac.ke/","image":"/images/brands/must-logo.png","name":"MUST"},{"image":"/images/brands/mcg-logo.png","name":"Meru County Government"}],"cta":{"href":"/sponsors-partners","label":"Sponsorship Details"},"tiers":[{"description":"Headline visibility and premium exhibition space.","name":"Platinum"},{"description":"Prominent branding and speaking opportunities.","name":"Gold"},{"description":"Brand presence and exhibition booth.","name":"Silver"}]}', '2026-08-13T09:46:05.922Z', '2026-08-13T09:46:05.922Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('cf873807-8b3f-40dc-a728-28c45663eea5', '3495b681-6e19-4615-a8f1-f79f73e92515', 'meru-county', 2, 'Meru County: The Land of Prosperity', NULL, 'Meru is a highland County nestled on the fertile slopes of Mount Kenya in the Eastern Region. Spanning 7,003 sq km with a population of 1.5 million, it serves as a strategic gateway between Nairobi and the Northern Frontier.\n\nEconomic & Social Development\nMeru has experienced rapid economic growth, driven by a highly educated populace and a diverse economic base.\n\nAgriculture & Business: A global leader in Miraa (Khat), Macadamia, and Coffee production, alongside Tea, Bananas, Avocado, Tourism, Trade & Industry.', '/images/sections/meru-county.png', '{"cta":[{"href":"/about","label":"About us"}]}', '2026-08-13T09:46:05.922Z', '2026-08-13T09:46:05.922Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('f9dcddb7-ba20-4c21-a4cc-6bb1ee1b535d', '3a229827-bf11-4c84-9ea7-b944ec0d0453', 'hero', 0, 'News & Updates', 'Latest announcements from the MIICCOF secretariat', NULL, NULL, '{}', '2026-08-13T09:46:07.307Z', '2026-08-13T09:46:07.307Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('0107a7b0-d685-469b-aecb-18691f8b41e4', '4631bc82-f001-4c02-b12e-d828387d9a15', 'mission', 2, 'Mission & Vision', NULL, NULL, NULL, '{"cards":[{"description":"To catalyse investment and trade for inclusive economic growth.","title":"Mission"},{"description":"A thriving investment destination with globally connected enterprises.","title":"Vision"}]}', '2026-08-13T09:46:06.108Z', '2026-08-13T09:46:06.108Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('1962f18b-31cb-4c34-9795-776018cc8999', '4631bc82-f001-4c02-b12e-d828387d9a15', 'body', 1, 'Our Story', NULL, 'Three institutions. One vision. A new chapter for Meru.\n\nThe Meru International Investors Conference and Consumer Fair (MIICCOF) was born from a unique tripartite partnership between the KNCCI Meru Chapter, Meru University of Science and Technology, and the Meru County GovernmentΓÇöuniting business, research, innovation and government to unlock Meru\'s potential.\n\nFor the first time, the business community, investors, researchers and innovators come together under one platform to showcase, connect and create opportunities.\n\nWith the support of the Governor of Meru County, the research and innovation strength of Meru University, and the networks and enterprise of KNCCI Meru, MIICCOF puts the best of Meru on displayΓÇöfrom agriculture and tourism to manufacturing, technology, trade and emerging enterprises.\n\nMIICCOF is more than a conference and trade fair. It is Meru opening its doors to the world and inviting the world to invest, partner and grow with us.', '/images/sections/about-tripartite.png', '{"logoUrl":"/images/logos/miictf-logo.png"}', '2026-08-13T09:46:06.108Z', '2026-09-14T05:15:44.824Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('3f79e9d7-c0ec-41dc-ae1c-5b2574adfe01', '4631bc82-f001-4c02-b12e-d828387d9a15', 'hero', 0, 'About MIICCOF', 'A platform for investment, trade and partnerships', NULL, '/images/hero/about-us-hero.jpeg', '{}', '2026-08-13T09:46:06.108Z', '2026-08-13T09:46:06.108Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('ef1e20a4-0e03-4b76-8543-297b97fc8d27', '4631bc82-f001-4c02-b12e-d828387d9a15', 'committee', 4, 'Organising Committee', 'The people making it happen', NULL, NULL, '{"anchorId":"organising","cards":[{"description":"Representing the County Government of Meru (MCG) as Vice Chairperson, overseeing trade facilitation.","image":"/images/committee/jacline-kanana.png","org":"Meru County Government","role":"Vice Chairperson, Trade","title":"Jackline Kanana"},{"description":"Providing legal counsel and governance oversight for the conference organising committee.","org":"Meru County Government","role":"Legal Advisor","title":"Liz Wanja Gikundi"},{"description":"Coordinating county government support and inter-agency collaboration for the event.","org":"Meru County Government","role":"MCG Representative","title":"John Kibwi Maingi"},{"description":"Championing youth inclusion and engagement across conference programmes and activities.","org":"Meru County Government","role":"Youth Affairs","title":"Alice Karimi"},{"description":"Representing the Meru County Government in logistics, policy coordination and public sector alignment.","org":"Meru County Government","role":"MCG Representative","title":"Kithinji Ruri"},{"description":"Representing Meru University of Science and Technology (MUST) as Chairperson of the Organising Committee.","image":"/images/committee/julius-ithae.jpg","org":"MUST","role":"Committee Chairperson","title":"Dr. Julius Ithae"},{"description":"Representing Meru University of Science and Technology in academic partnerships and research coordination.","image":"/images/committee/patrick-kubai.jpg","org":"MUST","role":"MUST Representative","title":"Dr. Patrick Kinyua Kubai"},{"description":"Contributing academic expertise and research partnerships from Meru University of Science and Technology.","org":"MUST","role":"MUST Representative","title":"Prof. Jackline Oparde"},{"description":"Supporting academic coordination and institutional partnerships from Meru University.","org":"MUST","role":"MUST Representative","title":"Prof. Amos Omano"},{"description":"Serving as Vice Chairperson of KNCCI ΓÇô Meru Chapter, supporting sponsor relations and business networking.","org":"KNCCI ΓÇô Meru Chapter","role":"Vice Chairperson","title":"Veronicah Kihenja"},{"description":"Serving as Director, guiding strategic initiatives and chamber operations for the conference.","org":"KNCCI ΓÇô Meru Chapter","role":"Director","title":"William Wambugu"},{"description":"Representing KNCCI Meru Chapter as Secretary, coordinating chamber activities and member engagement.","image":"/images/committee/martin-mbui.jpeg","org":"KNCCI ΓÇô Meru Chapter","role":"Secretary","title":"Martin Kiogora Mbui"}],"variant":"committee"}', '2026-08-13T09:46:06.108Z', '2026-09-14T05:15:51.185Z');
INSERT INTO `section` (id, pageId, `key`, `order`, title, subtitle, body, imageUrl, metadata, createdAt, updatedAt) VALUES ('f7750a7c-d909-4654-9da8-d1587c5eab6d', '4631bc82-f001-4c02-b12e-d828387d9a15', 'leadership', 3, 'Our Leadership', 'The team championing MIICCOF', NULL, NULL, '{"anchorId":"leadership","cards":[{"description":"Championing Meru\'s transformation into a premier investment destination through strategic partnerships and infrastructure development. Under his leadership, the county has prioritised investment in agriculture, tourism and trade infrastructure.","image":"/images/leadership/governor.png","imageBg":"white","role":"Governor, Meru County","title":"H.E. Isaac Mutuma M\'Ethingia"},{"description":"Leading academic innovation and research partnerships that drive the conference\'s thought leadership agenda. Prof. Odhiambo brings deep expertise in higher education and international collaboration.","image":"/images/leadership/vice-chancellor.webp","role":"Vice Chancellor MUST","title":"Prof. Romanus Odhiambo, Ph.D."},{"description":"Connecting the private sector with investment opportunities and championing trade facilitation across the region. Mr. Mungania represents the interests of Meru\'s business community.","image":"/images/leadership/chairman.jpeg","role":"Chairman KNCCI - Meru Chapter","title":"Mr. Joshua K. Mungania"}],"variant":"leadership"}', '2026-08-13T09:46:06.108Z', '2026-09-14T05:15:47.873Z');
