INSERT INTO `news` (id, title, slug, excerpt, content, coverImage, category, status, publishedAt, createdAt, updatedAt) VALUES ('41b4ae4b-f4db-4c09-97cc-d31f42f93bab', 'Sponsorship packages available', 'sponsorship-packages-available', 'Platinum, Gold and Silver sponsorship packages are now available.', 'Organisations interested in sponsoring MIICCOF can register as sponsors through the platform. The partnerships team will follow up with package details.', NULL, 'Sponsorship', 'PUBLISHED', '2026-08-13T09:46:05.225Z', '2026-08-08T08:36:38.069Z', '2026-08-13T09:46:07.745Z');
INSERT INTO `news` (id, title, slug, excerpt, content, coverImage, category, status, publishedAt, createdAt, updatedAt) VALUES ('d0a953d7-e46f-4147-8ff5-98b030413428', 'Welcome to the MIICCOF digital platform', 'welcome-to-the-miictf-digital-platform', 'Register as a delegate, sponsor or exhibitor and follow conference updates here.', 'The MIICCOF digital platform is now live. Delegates, sponsors and exhibitors can register online, receive announcements and access conference information in one place.', NULL, 'Announcement', 'PUBLISHED', '2026-08-13T09:46:05.225Z', '2026-08-08T08:36:38.050Z', '2026-08-13T09:46:07.643Z');
INSERT INTO `news` (id, title, slug, excerpt, content, coverImage, category, status, publishedAt, createdAt, updatedAt) VALUES ('f24437c9-e4e3-4706-b597-d6740a256007', 'Call for exhibitors now open', 'call-for-exhibitors-now-open', 'Organisations can now register to exhibit at the consumer fair.', 'Exhibitor registration is open. Booths are allocated on a first-come basis across themed exhibition halls at the consumer fair. Register early to secure your space.', NULL, 'Trade Fair', 'PUBLISHED', '2026-08-13T09:46:05.225Z', '2026-08-08T08:36:38.058Z', '2026-08-13T09:46:07.723Z');
